*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF08022.xml";
scwin.v_SaveKind = ""; //신규/수정 구분
scwin.vBzProcsNo = ""; //업무처리번호
scwin.vIsurCd = ""; //발행기관
scwin.v_UpdParam = new Array(); //Parent에서 넘어온 데이터들
scwin.vIsurCd = ""; //종목코드
scwin.vIsuQty = 0; //발행수량
scwin.vAcptNo = ""; //접수번호

scwin.vNapplShrs = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //미반영건수

/********************************************** 
 * 함수명 : fn_CheckForm(kind)
 * Params : kind( N:신규, U:수정)
 * 설명    : Form Validation Check
 ***********************************************/
scwin.fn_CheckForm = function(kind) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(edt_HALFWY_REDMPT_DD) == "") {
        $c.win.alert("[중도상환일]을 입력하세요.");
        edt_HALFWY_REDMPT_DD.focus();
        return false;
    } else if ($c.stf.getObjectValue(edt_CHG_LIST_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    } else if (vCurDate >= $c.stf.getObjectValue(edt_CHG_LIST_DD)) {
        $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }
    return true;
};


/********************************************** 
 * 함수명 : fn_check_numeric()
 * 설명    : 숫자입력체크
 ***********************************************/
scwin.fn_check_numeric = function() {
    var key = window.event ? window.event.keyCode : window.event.which;

    //방향키 좌우, home, end (35,36,37,39)
    // del, back space (8, 46)
    if ((event.shiftKey == false) && ((key > 47 && key < 58) || (key > 95 && key < 106) ||
            key == 35 || key == 36 || key == 37 || key == 39 ||
            key == 8 || key == 46)) {
        return true;
    } else {
        return false;
    }
};



/********************************************** 
 * 함수명 : fn_only_number()
 * 설명    : 숫자만 입력 가능
 ***********************************************/
scwin.fn_only_number = function() {
    var key = window.event ? window.event.keyCode : window.event.which;
    if ((key < 48) || (key > 57)) {
        window.event.returnValue = false;
    }
};



/********************************************** 
 * 함수명 : fn_save_qty_appl_insert()
 * 설명    : 수량변경 > 신청 내역 > 저장(신규)
 ***********************************************/
scwin.fn_save_qty_appl_insert = function() {
    if ($c.en.fn_CheckForm(scwin.v_SaveKind) == false) return;
    var TR_JOB = 'I';

    //Transaction 처리전 안내문구
    if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) == "") {
        txb_INCDEC_APPL_LIST_SHRS.setValue("0");
    }
    if (parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) > 0) {
        LastJob = '저장'; //list_common_etn.js에 있는 상장메세지처리관련
        //var rstlMsg = confirm("[증감증권수]는 0 이하의 수만 입력가능합니다.\n\n현재 상태로 [저장] 처리하시겠습니까?");
        //if (rstlMsg == false) {			
        //	return;
        //}
        $c.win.alert("[증감증권수]는 0 이하의 수만 입력가능합니다.");
        return;
    } else {
        var isNApplShrs = true;

        //제출에서 오는 변경후 데이터가 틀릴 수 있으므로, 미반영에 대한 체크를 한 번 더 해줌
        var totShrs = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
        if (totShrs != parseInt(txb_CHG_AF_LIST_SHRS.getValue())) {
            isNApplShrs = confirm("[미반영건수] 가 " + scwin.vNapplShrs + " 건 있습니다.\n[변경후 증권수] 에 반영하고 처리합니다.\n\n[저장] 처리하시겠습니까?");
            if (!isNApplShrs) {
                return;
            } else {
                LastJob = '저장'; //list_common_etn.js에 있는 상장메세지처리관련
                txb_CHG_AF_LIST_SHRS.setValue(parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue()));
            }
        } else {
            if (!$c.lce.fn_isProcess(TR_JOB)) {
                return;
            } else {
                txb_CHG_AF_LIST_SHRS.setValue(parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue()));
            }
        }
    }
    var vScrenId = "SCREN_ID=" + scwin.vScrenID;
    var vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    var vSrvMethod = "&method=insertQtyApplDtl";
    scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo); //업무처리번호 새로 지정
    scwin.vIsurCd = scwin.v_UpdParam[1]; //발행기관코드

    trs_Save.Action = "/etn/EtnChgList.do?" + vScrenId + vScrenTpId + vSrvMethod;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + TR_JOB_INSERT + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_708 + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + scwin.vIsurCd + ",LD_MKT_TP_CD=1" + ",TRANSTR_EMP_NO=" + js_emp_no + ",ACPT_NO=" + scwin.vAcptNo;
    trs_Save.Post();
};


/********************************************** 
 * 함수명 : fn_select_isu_init()
 * 설명    : 종목코드에 대한 발행회사 조회 / 신규시 초기화됨
 ***********************************************/
scwin.fn_select_appl_init = function() {
    //조회조건
    /*	1. 수량변경 신청내역 조회	*/
    var url = "/etn/EtnChgList.do?method=selectQtyApplDetail";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ACPT_NO=" + scwin.vAcptNo;
    //	url += "&SRCH_ISU_CD=" + v_UpdParam[0];
    //	url += "&SRCH_COM_CD=" + v_UpdParam[1];

    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();

    //제출에서 오는 변경후 데이터가 틀릴 수 있으므로, 미반영에 대한 체크를 한 번 더 해줌
    //txb_CHG_AF_LIST_SHRS.text = parseInt(txb_CHG_PRE_LIST_SHRS.text) + parseInt(txb_INCDEC_APPL_LIST_SHRS.text) + parseInt(txb_NAPPL_SHRS.text);
    //미반영건수 (저장시 체크하기 위함. 이유는 제출시스템에서 오는 데이터는 미반영건수에 대한 데이터가 아닐 수 있으므로, 그냥 저장할 때 체크해야 함)
    scwin.vNapplShrs = parseInt(txb_NAPPL_SHRS.getValue());
};


/********************************************** 
 * 함수명 : fn_parentRefresh()
 * 설명    : Parent 화면 Refresh()
 ***********************************************/
scwin.fn_parentRefresh = function() {
    //Parent 신청내역 화면 Refresh
    var parentWin = $c.frame.path("../");
    parentWin.txb_SearchIsuCd.setValue(txb_ISU_CD.getValue());
    parentWin.txb_SearchIsuNm.setValue(txb_ISU_NM.getValue());
    $c.stf.setObjectValue(parentWin.cmb_ISUR_CD, scwin.vIsurCd);
    parentWin.fn_list_qty_appl(scwin.vIsurCd, txb_ISU_CD.getValue());
    parentWin.fn_list_sync();
};
scwin.btn_QtyIsuClose_onclick = async function() {
    //닫기(수량변경)
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    //Form onload event
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    var parentWin = $c.frame.path("../");

    //Transaction 구분: 신규(N), 수정(U)
    scwin.v_SaveKind = parentWin.vQtyApplKind;
    scwin.v_UpdParam = parentWin.v_UpdQtyApplParam;
    scwin.vAcptNo = parentWin.clickAcptNo;
    if (scwin.v_SaveKind == "N") {
        //

    } else if (scwin.v_SaveKind == "U") {
        btn_QtyIsuSave.src = "../img/btn_save_d.gif";
        btn_QtyIsuSave.setDisabled(true);
    }

    //데이터 조회
    scwin.fn_select_appl_init();
};
scwin.dts_Itm_IsurDtl_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lce.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.lce.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.img_LIST_DD_onclick = function() {
    //수량변경 > 신청 내역 > 중도상환일 달력 클릭
    popUpCalendar2(edt_HALFWY_REDMPT_DD);
};
scwin.img_BENFCERT_ESTBREPUR_DD_onclick = function() {
    //수량변경 > 신청 내역 > 변경상장일 달력 클릭
    popUpCalendar2(edt_CHG_LIST_DD);
};
scwin.btn_QtyIsuSave_onclick = function() {
    //수량변경 > 신청 내역 > 저장버튼 클릭
    scwin.fn_save_qty_appl_insert();
};
scwin.txb_INCDEC_APPL_LIST_SHRS_onkeyup = function() {
    //수량변경 > 신청 내역 > 세부 > 증감증권수 onkeyup
    if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) == "-0") {
        txb_INCDEC_APPL_LIST_SHRS.setValue("0");
    }
    var rsltCalc = 0;
    if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) == "" || $c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) == "-") {
        rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
    } else {
        rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
    }
    txb_CHG_AF_LIST_SHRS.setValue(rsltCalc);
};
scwin.txb_LP_HD_QTY_OnKeyUp = function(keycode, skeycode) {
    //수량변경 > 신청 내역 > 세부 > LP보유수량 onkeyup
    if ($c.ut.trim(txb_LP_HD_QTY.getValue()) == "-0") {
        txb_LP_HD_QTY.setValue("0");
    }
};
scwin.txb_NAPPL_SHRS_onkeyup = function() {
    //수량변경 > 신청 내역  > 세부 > 미반영증권수 onkeyup
    if ($c.ut.trim(txb_NAPPL_SHRS.getValue()) == "-0") {
        txb_NAPPL_SHRS.setValue("0");
    }
    var rsltCalc = 0;
    if ($c.ut.trim(txb_NAPPL_SHRS.getValue()) == "" || $c.ut.trim(txb_NAPPL_SHRS.getValue()) == "-") {
        rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
    } else {
        rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
    }
    txb_CHG_AF_LIST_SHRS.setValue(rsltCalc);
};
